import{_ as n}from"./chunks/architecture.Cs8uKTTN.js";import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Konzepte","description":"","frontmatter":{},"headers":[],"relativePath":"de/concepts/overview.md","filePath":"de/concepts/overview.md","lastUpdated":1784903584000}'),r={name:"de/concepts/overview.md"};function o(p,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="konzepte" tabindex="-1">Konzepte <a class="header-anchor" href="#konzepte" aria-label="Permalink to &quot;Konzepte&quot;">​</a></h1><h2 id="architektur" tabindex="-1">Architektur <a class="header-anchor" href="#architektur" aria-label="Permalink to &quot;Architektur&quot;">​</a></h2><p>swag2mcp fungiert als Brücke zwischen API-Spezifikationen und LLM-Agenten:</p><img src="'+n+`" width="800" alt="swag2mcp-Architektur"><h2 id="kernkonzepte" tabindex="-1">Kernkonzepte <a class="header-anchor" href="#kernkonzepte" aria-label="Permalink to &quot;Kernkonzepte&quot;">​</a></h2><p><strong>Spec</strong> — ein logischer Container, der eine API-Domain oder einen API-Dienst repräsentiert (z. B. YouTube, Binance, Open-Meteo). Jede Spec hat eine eindeutige <code>domain</code>, eine <code>base_url</code>, optional <code>auth</code> und enthält eine oder mehrere Collections. Sie können auch <code>llm_instruction</code> setzen — einen kurzen Hinweis, der in den swag2mcp-System-Prompt eingefügt wird und dem LLM sagt, wofür diese Spec ist und wann sie verwendet werden soll. Mehr erfahren: <a href="./specs">Specs</a>.</p><p><strong>Collection</strong> — eine einzelne OpenAPI/Swagger/Postman-Datei, die eine bestimmte API beschreibt. Sie verweist auf einen <code>location</code> (URL oder lokalen Dateipfad). Eine Spec kann mehrere Collections haben — zum Beispiel könnte die &quot;meteo&quot;-Spec die Collections &quot;Forecast&quot;, &quot;Air Quality&quot; und &quot;Marine&quot; haben, die jeweils auf eine andere Spezifikationsdatei verweisen. Mehr erfahren: <a href="./collections">Collections</a>.</p><p><strong>Tag</strong> — eine Kategorie von Endpunkten innerhalb einer Collection. Hilft dem LLM, die richtigen Operationen genauer zu finden. Mehr erfahren: <a href="./tags">Tags</a>.</p><p><strong>Endpunkt</strong> — eine bestimmte HTTP-Methode + Pfad (z. B. <code>GET /api/users</code>). Der LLM kann einen Endpunkt anhand der Beschreibung finden, seine Parameter und Schemata inspizieren und ihn dann aufrufen. Mehr erfahren: <a href="./endpoints">Endpunkte</a>.</p><p><strong>Arbeitsbereich</strong> — das Verzeichnis, in dem swag2mcp Konfiguration, Spec-Cache, gespeicherte Antworten und Auth-Skripte speichert. Mehr erfahren: <a href="./workspace">Arbeitsbereich</a>.</p><h2 id="wie-es-funktioniert" tabindex="-1">Wie es funktioniert <a class="header-anchor" href="#wie-es-funktioniert" aria-label="Permalink to &quot;Wie es funktioniert&quot;">​</a></h2><ol><li><p><strong>Eine Spec oder Collection hinzufügen</strong> — in der YAML-Konfiguration definieren (<code>~/.swag2mcp/swag2mcp.yaml</code>). Zum Beispiel:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">specs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">domain</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Dad Joke API</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://icanhazdadjoke.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    collections</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">llm_title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Jokes</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">        location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://raw.githubusercontent.com/mmadfox/swag2mcp/main/specs/dadjoke.yaml</span></span></code></pre></div></li><li><p><strong>swag2mcp parst jede Collection</strong> — erstellt Tags und Endpunkte, indiziert sie für die Suche.</p></li><li><p><strong>LLM findet den richtigen Endpunkt</strong> — über MCP-Tools (<code>search</code>, <code>endpoint_by_tag</code>, <code>inspect</code>) sucht der LLM nach einem passenden Endpunkt anhand der Beschreibung, prüft seine Parameter und das Anforderungsschema.</p></li><li><p><strong>LLM ruft den Endpunkt auf</strong> — über das MCP-Tool <code>invoke</code> sendet der LLM die Anfrage. swag2mcp validiert jeden Eingabeparameter gegen das OpenAPI-Schema des Endpunkts (Pfadparameter, Abfrageparameter, Header, Anforderungstext), bevor der Aufruf erfolgt. Wenn etwas nicht zum Schema passt, erhält der LLM eine klare Fehlermeldung, die erklärt, was falsch ist. Nach der Validierung führt swag2mcp den echten HTTP-Aufruf aus und gibt das Ergebnis zurück.</p></li><li><p><strong>Ergebnis geht zurück an den LLM</strong> — die API-Antwort wird an den Agenten zurückgegeben. Große Antworten werden im Arbeitsbereich gespeichert und können mit drei speziellen MCP-Tools erkundet werden: <code>response_outline</code> (Struktur anzeigen), <code>response_compress</code> (auf eine repräsentative Stichprobe verkleinern) und <code>response_slice</code> (bestimmte Fragmente extrahieren).</p></li></ol><p>swag2mcp ist eine Brücke zwischen LLMs und der Welt der APIs. Sie fügen API-Spezifikationen hinzu, und der LLM — über das MCP-Protokoll — findet die richtigen Endpunkte, inspiziert ihre Dokumentation und ruft sie auf. Alles, was Sie tun müssen, ist eine Spec hinzuzufügen und den MCP-Server zu starten.</p><blockquote><p><strong>Die Konfiguration kann jederzeit bearbeitet werden.</strong> Die YAML-Konfigurationsdatei (<code>~/.swag2mcp/swag2mcp.yaml</code>) kann von Hand bearbeitet werden — Specs hinzufügen, Auth ändern, Einstellungen anpassen. Nach jeder Bearbeitung starten Sie den MCP-Server (<code>swag2mcp mcp</code>) neu, damit die Änderungen wirksam werden.</p></blockquote><h2 id="hierarchie" tabindex="-1">Hierarchie <a class="header-anchor" href="#hierarchie" aria-label="Permalink to &quot;Hierarchie&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Spec (domain, z. B. &quot;meteo&quot;)</span></span>
<span class="line"><span>  └── Collection 1 (Spezifikationsdatei, z. B. forecast.yml)</span></span>
<span class="line"><span>        └── Tag 1 (Kategorie)</span></span>
<span class="line"><span>              └── Endpunkt (GET /api/forecast)</span></span>
<span class="line"><span>              └── Endpunkt (POST /api/forecast)</span></span>
<span class="line"><span>        └── Tag 2</span></span>
<span class="line"><span>              └── Endpunkt (GET /api/forecast/{id})</span></span>
<span class="line"><span>  └── Collection 2 (Spezifikationsdatei, z. B. air-quality.yml)</span></span>
<span class="line"><span>        └── Tag 3</span></span>
<span class="line"><span>              └── Endpunkt (GET /api/air-quality)</span></span></code></pre></div>`,16)])])}const m=i(r,[["render",o]]);export{g as __pageData,m as default};
